const envelope = $json;
if (!envelope || envelope.type !== 'event.reminder_due' || envelope.version !== 1) throw new Error('Unsupported CrowdRelay event');
const data = envelope.data ?? {};
if (!data.fan?.email || !data.event?.slug || !data.event?.title || !data.event?.starts_at) throw new Error('Missing reminder fields');
const base = ("https://virya.music" || '').replace(/\/$/, '');
if (!base) throw new Error('Missing CROWDRELAY_PUBLIC_SITE_URL');
return [{ json: { event_id: envelope.id, mail: {
  template: 'crowdrelay-event-reminder', to: data.fan.email,
  variables: { display_name: data.fan.display_name ?? null, locale: data.fan.locale ?? 'pl-PL', reminder_kind: data.reminder_kind, event_title: data.event.title, starts_at: data.event.starts_at, doors_at: data.event.doors_at ?? null, venue: data.event.venue ?? null, venue_address: data.event.venue_address ?? null, event_url: `${base}/live/${encodeURIComponent(data.event.slug)}`, ticket_url: data.event.ticket_url ?? `${base}/live/${encodeURIComponent(data.event.slug)}` },
  idempotency_key: envelope.id
}} }];

